  @override
  void operator []=(String key, List<ModelRef> value) =>
      throw UnsupportedError('read-only');

  @override
  void clear() => throw UnsupportedError('read-only');

  @override
  List<ModelRef>? remove(Object? key) => throw UnsupportedError('read-only');
}

