    /// The app path with an EMPTY store (no overrides at all).
    ModelRolesResolver appResolverNoSmol() => ModelRolesResolver(
      config: ModelRolesConfig(
        roles: StoreBackedRolesMap(TaskModelsStore.inMemory()),
      ),
