      expect(cli.sameResolutionAs(app), isTrue);
    });

    test('smol equal to main normalizes to main-only on BOTH paths', () {
      final sameRef = ModelRef(
        provider: 'anthropic',
        modelId: 'claude-sonnet-x',
        apiKeyName: 'ANTHROPIC_API_KEY',
