        expect(wiring.window, 1000000);
        expect(wiring.conversationWindow, 1000000);
        expect(wiring.settings.reserveTokens, 16384);
        expect(
          wiring.conversationWindow - wiring.settings.reserveTokens,
          1000000 - 16384,
