    if (projectDir != null) {
      final project = loadProjectContextWindowCap(projectDir);
      if (project != null) return project;
    }
    final home = desktopHomeDir();
    if (home == null) return null;
    return loadCliConfig(home).contextWindowCap;
  } on Object {
    return null;
  }
}
